typedef unsigned int u_int;
#define NGL_NUM_LIGHTCATS 8
#define NGL_LIGHTCAT_SHIFT 24
#define NGL_MAX_MATERIAL_TEXTURES 12
#define START_PROF_TIMER(x)
#define STOP_PROF_TIMER(x)
#define SCE_MATRIX(x) ((float*)(x))
class nglVector { public: float v[4]; inline operator float*(){return v;} inline float& operator[](int i){return v[i];} } __attribute__((aligned(16)));
class nglMatrix { public: nglVector x,y,z,w; inline operator float*(){return (float*)this;} };
typedef nglVector nglPlane;
struct nglFrustum { nglPlane Planes[6]; };
struct nglTexture;
struct nglMesh { u_int Flags; void* File; nglMesh* NextMesh; u_int DataSize; char Name[32]; nglVector SphereCenter; float SphereRadius; };
typedef void (*nglCustomLightFn)(u_int*&,void*);
struct nglLightNode { nglLightNode* Next[NGL_NUM_LIGHTCATS]; nglLightNode* LocalNext[NGL_NUM_LIGHTCATS]; u_int LightCat; u_int Type; nglCustomLightFn NodeFn; void* NodeData; };
struct nglLightContext { nglLightNode VertexHead; nglLightNode TextureHead; bool LocalVertexListEmpty; bool LocalTextureListEmpty; nglVector Ambient; };
struct nglPointLightInfo { nglVector Pos; nglVector Color; float Near; float Far; };
struct nglPointProjectorLightInfo { nglVector Pos; nglVector Color; float Range; u_int BlendMode; u_int BlendModeConstant; nglTexture* Tex; };
struct nglDirProjectorLightInfo { u_int BlendMode; u_int BlendModeConstant; nglTexture* Tex; nglVector Scale; nglVector Pos; nglVector Xaxis; nglVector Yaxis; nglVector Zaxis; nglMatrix WorldToUV; nglMatrix UVToWorld; nglFrustum Frustum; };
enum { NGLLIGHT_DIRECTIONAL, NGLLIGHT_FAKEPOINT, NGLLIGHT_TRUEPOINT, NGLLIGHT_PROJECTED_DIRECTIONAL, NGLLIGHT_PROJECTED_POINT };
extern nglLightContext* nglGlobalLightContext;
extern nglLightContext* nglCurLightContext;
extern "C" void sceVu0ApplyMatrix(float*,float*,float*);
extern bool nglIsSphereVisible(nglFrustum*,const nglVector&,float);
__asm__(".equ nglGlobalLightContext,0x004BC0B0");
__asm__(".equ nglCurLightContext,0x004BC0B4");
__asm__(".equ sceVu0ApplyMatrix,0x003BC320");
__asm__(".equ nglIsSphereVisible__FP10nglFrustumRC9nglVectorf,0x0039B328");
inline int nglSpheresIntersect(nglVector& Center1,float Radius1,nglVector& Center2,float Radius2){nglVector V;float DistSqr,Range;V[0]=Center1[0]-Center2[0];V[1]=Center1[1]-Center2[1];V[2]=Center1[2]-Center2[2];V[3]=Center1[3]-Center2[3];DistSqr=V[0]*V[0]+V[1]*V[1]+V[2]*V[2];Range=Radius1+Radius2;return DistSqr<=Range*Range;}
void nglDetermineLocalLights( nglLightContext* Context, nglMesh* Mesh, nglMatrix& LocalToWorld, nglTexture** Textures, u_int& NTextures )
{
  START_PROF_TIMER( proftimer_section_lighting );

  if ( Context )
    nglCurLightContext = Context;
  else
    nglCurLightContext = nglGlobalLightContext;

  nglCurLightContext->LocalVertexListEmpty = true;
  nglCurLightContext->LocalTextureListEmpty = true;

  nglVector WorldPos;
  sceVu0ApplyMatrix( WorldPos, SCE_MATRIX( LocalToWorld ), Mesh->SphereCenter );

  for ( int i = 0; i < NGL_NUM_LIGHTCATS; i++ )
  {
    nglCurLightContext->VertexHead.LocalNext[i] = &nglCurLightContext->VertexHead;
    nglCurLightContext->TextureHead.LocalNext[i] = &nglCurLightContext->TextureHead;

    if ( !( Mesh->Flags & ( 1 << ( NGL_LIGHTCAT_SHIFT + i ) ) ) )
      continue;

    nglLightNode* LightNode = nglCurLightContext->VertexHead.Next[i];
    while ( LightNode != &nglCurLightContext->VertexHead )
    {
      bool Success = false;
      if ( LightNode->Type == NGLLIGHT_TRUEPOINT || LightNode->Type == NGLLIGHT_FAKEPOINT )
      {
        nglPointLightInfo* Light = (nglPointLightInfo*)LightNode->NodeData;
        if ( nglSpheresIntersect( Light->Pos, Light->Far, WorldPos, 0.0f ) )
          Success = true;
      }
      else
      if ( LightNode->Type == NGLLIGHT_DIRECTIONAL )
        Success = true;

      if ( Success )
      {
        LightNode->LocalNext[i] = nglCurLightContext->VertexHead.LocalNext[i];
        nglCurLightContext->VertexHead.LocalNext[i] = LightNode;
        nglCurLightContext->LocalVertexListEmpty = false;
      }

      LightNode = LightNode->Next[i];
    }

    LightNode = nglCurLightContext->TextureHead.Next[i];
    while ( LightNode != &nglCurLightContext->TextureHead )
    {
      bool Success = false;
      if ( LightNode->Type == NGLLIGHT_PROJECTED_POINT )
      {
        nglPointProjectorLightInfo* Light = (nglPointProjectorLightInfo*)LightNode->NodeData;
        if ( nglSpheresIntersect( Light->Pos, Light->Range, WorldPos, Mesh->SphereRadius ) )
        {
          Textures[NTextures++] = Light->Tex;
          Success = true;
        }
      }
      else
      if ( LightNode->Type == NGLLIGHT_PROJECTED_DIRECTIONAL )
      {
        nglDirProjectorLightInfo* Light = (nglDirProjectorLightInfo*)LightNode->NodeData;
        if ( nglIsSphereVisible( &Light->Frustum, WorldPos, Mesh->SphereRadius ) )
        {
          Textures[NTextures++] = Light->Tex;
          Success = true;
        }
      }

      if ( Success )
      {
        LightNode->LocalNext[i] = nglCurLightContext->TextureHead.LocalNext[i];
        nglCurLightContext->TextureHead.LocalNext[i] = LightNode;
        nglCurLightContext->LocalTextureListEmpty = false;
      }

      if ( NTextures == NGL_MAX_MATERIAL_TEXTURES )
        break;

      LightNode = LightNode->Next[i];
    }
  }
  STOP_PROF_TIMER( proftimer_section_lighting );
}
